// Bench script for the Preview's pure-TS hot paths (issue #41).
//
// Runs against the synthetic fixtures generated by
// `cargo run -p toolpath-cli --bin gen_synthetic_path`. Prints median /
// p95 / max over N iterations per (size × operation) cell. Intended for
// tracking wins from #38 (markdown memo) and #39 (buildTree deps narrow).
//
// Usage (from `crates/toolpath-desktop/frontend`):
//
//   bun run bench                       # default: all sizes it can find
//   bun run src/lib/__bench__/preview.bench.ts --fixture ../../../bench/fixtures/synthetic-10k.path.json
//
// No external deps — just `performance.now()` and the modules under test.
// Render-time + memory measurements are the Tauri side and live in
// `BENCHMARKS.md` as a manual procedure.

import { readFileSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

import { classify } from "../classify";
import { buildTree, flattenChatHead, matchesFilter } from "../tree";
import { normalize } from "../viz";
import type { Document } from "../types";

const ITERATIONS_PER_OP = 10;
const KEYSTROKE_QUERIES = ["step", "step-0", "agent", "claude", "bench", "xyz"];

interface Stats {
  n: number;
  median: number;
  p95: number;
  max: number;
  mean: number;
}

function stats(samples: number[]): Stats {
  const sorted = [...samples].sort((a, b) => a - b);
  const n = sorted.length;
  const median = sorted[Math.floor(n / 2)];
  const p95 = sorted[Math.min(n - 1, Math.floor(n * 0.95))];
  const max = sorted[n - 1];
  const mean = sorted.reduce((a, b) => a + b, 0) / n;
  return { n, median, p95, max, mean };
}

function fmt(ms: number): string {
  if (ms < 1) return `${(ms * 1000).toFixed(0)}us`;
  if (ms < 100) return `${ms.toFixed(2)}ms`;
  return `${ms.toFixed(1)}ms`;
}

function printRow(label: string, s: Stats): void {
  console.log(
    `  ${label.padEnd(36)}` +
      `median=${fmt(s.median).padStart(8)}  ` +
      `p95=${fmt(s.p95).padStart(8)}  ` +
      `max=${fmt(s.max).padStart(8)}  ` +
      `mean=${fmt(s.mean).padStart(8)}  (n=${s.n})`,
  );
}

function time<T>(fn: () => T): [number, T] {
  const t0 = performance.now();
  const out = fn();
  const t1 = performance.now();
  return [t1 - t0, out];
}

function benchFixture(fixturePath: string): void {
  const raw = readFileSync(fixturePath, "utf8");
  const parseStart = performance.now();
  const doc = JSON.parse(raw) as Document;
  const parseMs = performance.now() - parseStart;

  const stepCount =
    "Path" in doc ? doc.Path.steps.length
    : "Graph" in doc ? doc.Graph.paths.flatMap((p) => ("$ref" in p ? [] : p.steps)).length
    : "Step" in doc ? 1
    : 0;

  console.log("");
  console.log(`── ${fixturePath} (${stepCount} steps, ${raw.length.toLocaleString()} bytes)`);
  console.log(`  JSON.parse:                         ${fmt(parseMs)}`);

  // normalize
  const normSamples: number[] = [];
  for (let i = 0; i < ITERATIONS_PER_OP; i++) {
    const [ms] = time(() => normalize(doc));
    normSamples.push(ms);
  }
  printRow("normalize(doc)", stats(normSamples));

  // buildTree (normalize + flattenTree)
  const buildSamples: number[] = [];
  for (let i = 0; i < ITERATIONS_PER_OP; i++) {
    const [ms] = time(() => buildTree(doc));
    buildSamples.push(ms);
  }
  printRow("buildTree(doc)", stats(buildSamples));

  // Warm a tree once for keystroke + classify benches.
  const { nodes, norm } = buildTree(doc);

  // matchesFilter — per-keystroke simulation over all nodes, "all" filter.
  const keystrokeSamples: number[] = [];
  for (let i = 0; i < ITERATIONS_PER_OP; i++) {
    const q = KEYSTROKE_QUERIES[i % KEYSTROKE_QUERIES.length];
    const [ms] = time(() => nodes.filter((n) => matchesFilter(n, q, "all")));
    keystrokeSamples.push(ms);
  }
  printRow("filter(matchesFilter) per keystroke", stats(keystrokeSamples));

  // flattenChatHead — HEAD-chain walk used by the transcript view.
  const chatSamples: number[] = [];
  for (let i = 0; i < ITERATIONS_PER_OP; i++) {
    const [ms] = time(() => flattenChatHead(norm));
    chatSamples.push(ms);
  }
  printRow("flattenChatHead(norm)", stats(chatSamples));

  // classify — per-step metadata extraction, run across every step.
  const classifySamples: number[] = [];
  for (let i = 0; i < ITERATIONS_PER_OP; i++) {
    const [ms] = time(() => {
      for (const s of norm.steps) classify(s);
    });
    classifySamples.push(ms);
  }
  printRow("classify × all steps", stats(classifySamples));
}

// ── Entry point ──────────────────────────────────────────────────────────

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const repoRoot = resolve(__dirname, "../../../../../..");

function defaultFixtures(): string[] {
  return [
    "bench/fixtures/synthetic-1k.path.json",
    "bench/fixtures/synthetic-5k.path.json",
    "bench/fixtures/synthetic-10k.path.json",
  ]
    .map((p) => resolve(repoRoot, p))
    .filter((p) => {
      try {
        readFileSync(p);
        return true;
      } catch {
        return false;
      }
    });
}

function main(): void {
  const argv = process.argv.slice(2);
  const fixtureArgIdx = argv.indexOf("--fixture");
  const fixtures =
    fixtureArgIdx >= 0 && argv[fixtureArgIdx + 1]
      ? [resolve(process.cwd(), argv[fixtureArgIdx + 1])]
      : defaultFixtures();

  if (fixtures.length === 0) {
    console.error(
      "No fixtures found. Generate them first:\n" +
        "  cargo run -p toolpath-cli --bin gen_synthetic_path -- --steps 1000 --out bench/fixtures/synthetic-1k.path.json\n" +
        "  cargo run -p toolpath-cli --bin gen_synthetic_path -- --steps 5000 --out bench/fixtures/synthetic-5k.path.json\n" +
        "  cargo run -p toolpath-cli --bin gen_synthetic_path -- --steps 10000 --out bench/fixtures/synthetic-10k.path.json\n",
    );
    process.exit(1);
  }

  console.log(`Preview bench — ${ITERATIONS_PER_OP} iterations per op`);
  console.log(`Node/Bun: ${process.version ?? "unknown"}`);

  for (const f of fixtures) benchFixture(f);
  console.log("");
}

main();
